import{_ as s,l as i,o as e,c as l,v as r,p as n,x as o,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Switch Transformer 论文","description":"","frontmatter":{"title":"Switch Transformer 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fedus-switch.md","filePath":"llm/fedus-switch.md","lastUpdated":1789023840000}'),c={name:"llm/fedus-switch.md"};function m(E,a,f,u,k,S){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="switch-transformer-论文" tabindex="-1">Switch Transformer 论文 <a class="header-anchor" href="#switch-transformer-论文" aria-label="Permalink to &quot;Switch Transformer 论文&quot;">​</a></h1><div class="epigraph"><p>每个 token 只进一个专家。路由变简单，容量仍可随专家数线性涨，训练却不再被 top-2 的实现细节绑住。</p><footer>—— Fedus, Zoph, Shazeer, Switch Transformers: Scaling to Trillion Parameter Models with Simple and Efficient Sparsity</footer></div><p>主干已有 <a href="/llm/switch-transformer">Switch Transformer</a> 课。附录对照 <strong>Fedus、Zoph、Shazeer 原文</strong> 的问题设定与稳定性配方：相对 GShard 的 \\(k=2\\)，他们把开关收到 \\(k=1\\)，并系统写容量因子、辅助损失、专家 dropout。上一篇附录是词表；本篇起 MoE 对照链。不把 GShard 公式再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GShard 已经把 MoE 接到 Transformer，但 \\(k=2\\) 让调度、容量桶、通信更绕。作者问：\\(k=1\\) 质量掉多少？若可接受，能否用更多专家把参数容量补回，同时保持与稠密模型同量级的 FLOPs？第二问是可复现的稳定训练：早期 MoE 的 NaN、崩溃、尺度爆炸。</p><p>万亿参数是标题中的尺度叙事：稀疏使参数与 FLOPs 解耦。评测含翻译、闭包式预训练任务，以及他们报告的不稳定案例。</p><h3 id="为何-仍叫-moe" tabindex="-1">为何 \\(k=1\\) 仍叫 MoE <a class="header-anchor" href="#为何-仍叫-moe" aria-label="Permalink to &quot;为何 $k=1$ 仍叫 MoE&quot;">​</a></h3><p>不同 token 仍走不同 FFN 参数，总库随 \\(N\\) 涨。不是稠密 FFN。代价是选错没有第二专家插值。<span class="marginnote">原文讨论是否把路由概率 \\(p_{i^*}\\) 乘回专家输出——这正是主干<a href="/llm/moe-router-gradient">路由器梯度</a>课的接口。附录只强调：论文把它当作稳定性与学习信号的一部分，而不是可有可无的实现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="、容量与辅助损失" tabindex="-1">\\(k=1\\)、容量与辅助损失 <a class="header-anchor" href="#、容量与辅助损失" aria-label="Permalink to &quot;$k=1$、容量与辅助损失&quot;">​</a></h3><p>路由 softmax 后取 argmax 专家。容量因子截断过载 token。辅助损失拉专家频率与平均概率。他们还写了专家 dropout、较小的路由 z-loss 一类稳定项（与后文 z-loss 对照衔接）。实现在 TPU 上按专家分片。</p>',11)),(e(),n(d,null,{default:o(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%20%E9%9A%90%E7%8A%B6%E6%80%81%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%20softmax%22%5D%0A%20%20R%20--%3E%20K1%5B%22k%3D1%20%E9%80%89%E4%B8%80%E4%B8%AA%E4%B8%93%E5%AE%B6%22%5D%0A%20%20K1%20--%3E%20CF%5B%22%E5%AE%B9%E9%87%8F%E6%A7%BD%EF%BC%9A%E6%BB%A1%E5%88%99%20drop%22%5D%0A%20%20CF%20--%3E%20E%5B%22%E5%8D%95%E4%B8%AA%E4%B8%93%E5%AE%B6%20FFN%22%5D%0A%20%20AUX%5B%22%E8%BE%85%E5%8A%A9%E5%9D%87%E8%A1%A1%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20R%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(k=1\\) 降低通信与实现复杂度，使扩大 \\(N\\) 更可行。稀疏度 \\(1/N\\) 高于 Mixtral 式 \\(k=2,N=8\\)。论文用实验主张质量损失有限、可用专家数换回。稳定性来自配方组合，不是单一技巧：容量、辅助损失、精度、初始化一起上。</p><p>Drop 的 token 本层无专家贡献，见主干<a href="/llm/moe-capacity-factor">容量因子</a>。原文把 \\(\\mathrm{CF}\\) 当作一等超参做了消融，而不是隐藏在代码里。</p><p><span class="marginnote">标题里的 trillion 是稀疏参数计数。引用「万亿模型」必须同时写激活 FLOPs 与专家数，否则与稠密万亿不可比。</span></p><h3 id="与后续-dropless-expert-choice" tabindex="-1">与后续 Dropless / Expert-choice <a class="header-anchor" href="#与后续-dropless-expert-choice" aria-label="Permalink to &quot;与后续 Dropless / Expert-choice&quot;">​</a></h3><p>原文默认有 drop 的静态容量。MegaBlocks 的 Dropless、Zhou 等的 Expert Choice 是后继对「不要丢 / 谁来选」的翻案。对照链下一篇就是 Expert Choice。不要把 2021 配方写成 MoE 的终点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>TPU 切片、Mesh 与今日 GPU EP 的通信模式不同，吞吐数字不能直接搬。\\(k=1\\) 在 Mixtral 一代产品里并未成为唯一默认——质量与实现栈变了。论文的贡献是简化开关 + 把稳定训练写成可抄的清单，以及参数–计算解耦的实证。</p><p>不要用标题数字当自家模型的参数声明。复现应锁辅助损失系数、\\(\\mathrm{CF}\\)、\\(k\\) 与精度。</p><p><span class="marginnote">文献名 <em>Switch Transformers: Scaling to Trillion Parameter Models with Simple and Efficient Sparsity</em>。作者 William Fedus、Barret Zoph、Noam Shazeer。期刊版本见 JMLR。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>原文主张 \\(k=1\\) 的 Switch 路由，用更多专家换容量、保持 FLOPs。</li><li>容量因子、辅助损失、专家 dropout 是稳定性清单的一部分。</li><li>万亿指稀疏参数，须与激活量一起报。</li><li>后续 Dropless / EC 改的是本文化的 drop 与 token-choice。</li><li>出处：Fedus, Zoph, Shazeer, Switch Transformers。</li></ul>',12))])}const B=s(c,[["render",m]]);export{A as __pageData,B as default};
